using Microsoft.AspNetCore.Http;using Microsoft.Extensions.Logging.Abstractions;using Microsoft.Extensions.Options;using SchoolERP.Api.Configuration;using SchoolERP.Api.Logging;using Xunit;namespace SchoolERP.UnitTests;
public sealed class LoggingFoundationTests{private static CorrelationIdMiddleware Middleware(RequestDelegate next)=>new(next,Options.Create(new SchoolErpLoggingOptions()));[Fact]public async Task Correlation_is_generated_and_returned_when_absent(){var c=new DefaultHttpContext();c.Response.Body=new MemoryStream();await Middleware(_=>Task.CompletedTask).InvokeAsync(c,NullLogger<CorrelationIdMiddleware>.Instance);await c.Response.StartAsync();var id=Assert.IsType<string>(c.Items[CorrelationIdMiddleware.ItemKey]);Assert.False(string.IsNullOrWhiteSpace(id));Assert.Equal(id,c.Response.Headers["X-Correlation-ID"]);}[Fact]public async Task Valid_correlation_is_propagated(){var c=new DefaultHttpContext();c.Request.Headers["X-Correlation-ID"]="abc-123";await Middleware(_=>Task.CompletedTask).InvokeAsync(c,NullLogger<CorrelationIdMiddleware>.Instance);await c.Response.StartAsync();Assert.Equal("abc-123",c.Items[CorrelationIdMiddleware.ItemKey]);}[Theory][InlineData("bad\nvalue")][InlineData("xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx")][InlineData("bad value") ]public async Task Invalid_correlation_is_replaced(string value){var c=new DefaultHttpContext();c.Request.Headers["X-Correlation-ID"]=value;await Middleware(_=>Task.CompletedTask).InvokeAsync(c,NullLogger<CorrelationIdMiddleware>.Instance);Assert.NotEqual(value,c.Items[CorrelationIdMiddleware.ItemKey]);}[Theory][InlineData("password")][InlineData("accessToken")][InlineData("Authorization")][InlineData("connectionString")]public void Secrets_are_fully_redacted(string key){var r=new LogRedactor();Assert.Equal("[REDACTED]",r.RedactValue(key,"super-secret"));}[Fact]public void Pii_masking_does_not_return_original(){var r=new LogRedactor();Assert.Equal("a***@example.com",r.RedactEmail("alice@example.com"));Assert.Equal("***4567",r.RedactPhone("+1 234 567"));}}
